package com.colonellp.ellamonitor;

import org.json.*;
import org.junit.Test;
import java.time.*;
import java.util.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import static org.junit.Assert.*;

/** Synthetic host-JVM checks: no owner device, network or database inputs. */
public class PopupHistoryTest {
    final Instant now=Instant.parse("2026-10-12T13:01:00Z");
    final ZoneId utc=ZoneOffset.UTC,london=ZoneId.of("Europe/London");
    PopupSelection selection(int period,boolean fixed){PopupSelection s=new PopupSelection();s.period=period;s.fixed=fixed;return s;}
    MonitorData.Metric metric(String id,String kind,String role,String channel)throws Exception{return new MonitorData.Metric(new JSONObject().put("id",id).put("name",id).put("kind",kind).put("source","sbms").put("role",role).put("batteryChannel",channel).put("voltage","sbms"));}
    HistoryData.Record row(Instant start,int seconds,double amps,double watts,double coverage,boolean partial)throws Exception{
        return new HistoryData.Record(new JSONObject().put("start",start.toString()).put("end",start.plusSeconds(seconds).toString()).put("partial",partial).put("samples",120)
            .put("values",new JSONArray().put(watts).put(amps).put(13).put(75)).put("ampCoverageSeconds",coverage).put("powerCoverageSeconds",coverage).put("voltCoverageSeconds",coverage)
            .put("netAh",amps*coverage/3600).put("netWh",watts*coverage/3600).put("currentLastAt",start.plusSeconds((long)coverage).toEpochMilli()).put("voltageLastAt",start.plusSeconds((long)coverage).toEpochMilli()));
    }
    HistoryData.Result result(MonitorData.Metric m,PopupHistory.Plan p,HistoryData.Record... rows){return new HistoryData.Result(m,p.query,Arrays.asList(rows),p.query.to.toString());}
    @Test public void rollingUsesElapsedQueryAndFullCalendarAxis(){for(int i=0;i<4;i++){PopupHistory.Plan p=PopupHistory.plan(now,selection(i,false),utc);assertEquals(now,p.query.to);assertTrue(p.end.isAfter(now));assertEquals(i==0?"minute":i<3?"hour":"day",p.query.resolution);}assertEquals("1.0 minutes",PopupHistory.caption(PopupHistory.plan(now,selection(0,false),utc),false));assertEquals(Instant.parse("2026-10-12T14:00:00Z"),PopupHistory.plan(now,selection(0,false),utc).end);}
    @Test public void fixedHourYesterdayWeekAndPastYearMonthHaveRequestedCaptions(){assertEquals("12pm to 1pm",PopupHistory.caption(PopupHistory.plan(now,selection(0,true),utc),true));assertEquals("Sunday 11th October",PopupHistory.caption(PopupHistory.plan(now,selection(1,true),utc),true));assertEquals("5th October to 11th October",PopupHistory.caption(PopupHistory.plan(now,selection(2,true),utc),true));PopupSelection s=selection(3,true);s.month="2025-09";PopupHistory.Plan p=PopupHistory.plan(now,s,utc);assertEquals("September '25",PopupHistory.caption(p,true));assertEquals(Instant.parse("2025-09-01T00:00:00Z"),p.query.from);assertEquals(Instant.parse("2025-10-01T00:00:00Z"),p.end);}
    @Test public void lastWeekCountsHoursNotEightIntersectingUtcDays(){PopupHistory.Plan p=PopupHistory.plan(now,selection(2,true),london);assertEquals(168,SummaryPeriods.expected(p.query,london));assertEquals(Instant.parse("2026-10-04T23:00:00Z"),p.query.from);}
    @Test public void daylightSavingAndMonthCountsFollowLocalCalendar(){PopupHistory.Plan p=PopupHistory.plan(Instant.parse("2026-10-26T12:00:00Z"),selection(2,true),london);assertEquals(169,SummaryPeriods.expected(p.query,london));PopupSelection s=selection(3,true);s.month="2026-09";assertEquals(30,SummaryPeriods.expected(PopupHistory.plan(now,s,london).query,london));assertEquals(25,SummaryPeriods.expected(PopupHistory.plan(Instant.parse("2026-10-26T12:00:00Z"),selection(1,true),london).query,london));}
    @Test public void sixHourPointsCountUnderlyingEntriesAndRetainGaps()throws Exception{PopupHistory.Plan p=PopupHistory.plan(now,selection(2,true),utc);List<HistoryData.Record> rows=new ArrayList<>();for(int i=0;i<12;i++)if(i!=8)rows.add(row(p.query.from.plusSeconds(i*3600),3600,i<6?2:4,i<6?26:52,3600,false));PopupHistory.Series s=PopupHistory.series(new HistoryData.Result(metric("load","electrical","load",""),p.query,rows,now.toString()),p,"current",false,true);assertEquals(11,s.captured);assertEquals(168,s.expected);assertEquals(2,s.points.size());assertEquals(2,s.points.get(0).value,0);assertEquals(4,s.points.get(1).value,0);assertTrue(s.points.get(0).complete);assertFalse(s.points.get(1).complete);}
    @Test public void meansAreWeightedByActualCoverageRatherThanZeroFilling()throws Exception{PopupHistory.Plan p=PopupHistory.plan(now,selection(2,true),utc);PopupHistory.Series s=PopupHistory.series(result(metric("load","electrical","load",""),p,row(p.query.from,3600,-2,-26,3600,false),row(p.query.from.plusSeconds(3600),3600,-8,-104,1800,false)),p,"current",false,true);assertEquals(4,s.points.get(0).value,0);assertFalse(s.points.get(0).complete);assertEquals(2,s.captured);}
    @Test public void sumIntegratesAhWhAndKeepsBatterySign()throws Exception{PopupHistory.Plan p=PopupHistory.plan(now,selection(0,true),utc);HistoryData.Result data=result(metric("battery","electrical","battery","sbmsBattery"),p,row(p.query.from,60,-3,-39,60,false),row(p.query.from.plusSeconds(60),60,1,13,60,false));PopupHistory.Series signed=PopupHistory.series(data,p,"current",true,false),usage=PopupHistory.series(data,p,"current",true,true),energy=PopupHistory.series(data,p,"watts",true,false);assertEquals("Ah",signed.unit);assertEquals(-2d/60,signed.points.get(1).value,1e-12);assertEquals(2d/60,usage.points.get(1).value,1e-12);assertEquals("Wh",energy.unit);assertEquals(-26d/60,energy.points.get(1).value,1e-12);assertEquals(SummaryPeriods.totals(data).charge,signed.points.get(1).value,1e-12);assertEquals(2,signed.captured);}
    @Test public void closedBoundaryAndFutureCheckpointCannotLeakIntoPlot()throws Exception{PopupHistory.Plan p=PopupHistory.plan(now,selection(0,false),utc);MonitorData.Metric m=metric("load","electrical","load","");HistoryData.Record valid=row(p.query.from,60,2,26,60,false),future=row(p.query.from.plusSeconds(60),60,9,117,10,true);HistoryData.Result data=new HistoryData.Result(m,p.query,Arrays.asList(valid,future),now.plusSeconds(10).toString());PopupHistory.Series s=PopupHistory.series(data,p,"current",false,true);assertEquals(1,s.points.size());assertEquals(1,s.captured);assertEquals(1,s.expected);}
    @Test public void negativeTemperatureAndSocUseActualLastReadings()throws Exception{PopupHistory.Plan p=PopupHistory.plan(now,selection(1,true),utc);HistoryData.Record t=new HistoryData.Record(new JSONObject().put("start",p.query.from.toString()).put("end",p.query.from.plusSeconds(3600).toString()).put("value",-13.25));PopupHistory.Series s=PopupHistory.series(result(metric("temp","temperature","",""),p,t),p,"temperature",false,false);assertEquals(-13.25,s.points.get(0).value,0);assertEquals("°C",s.unit);assertEquals(1,s.captured);HistoryData.Record battery=row(p.query.from,3600,-3,-39,3600,false);PopupHistory.Series soc=PopupHistory.series(result(metric("battery","electrical","battery","sbmsBattery"),p,battery),p,"stateOfCharge",false,false);assertEquals(75,soc.points.get(0).value,0);assertEquals("%",soc.unit);}
    @Test public void drawMagnitudeIsPresentationOnlyAndPreservesBatteryAndTemperatureSigns()throws Exception{
        MonitorData.Metric load=metric("load","electrical","load",""),battery=metric("battery","electrical","battery","sbmsBattery"),temperature=metric("temp","temperature","","");
        for(String field:new String[]{"current","watts","Ah","Wh"}){assertEquals(3,PopupHistory.displayValue(load,field,-3d),0);assertEquals(-3,PopupHistory.displayValue(battery,field,-3d),0);}
        assertEquals(-13,PopupHistory.displayValue(temperature,"temperature",-13d),0);assertNull(PopupHistory.displayValue(load,"current",null));assertEquals(-3,PopupHistory.displayValue(load,"voltage",-3d),0);
    }
    @Test public void wholeNumberAxisStepsNeverRoundTheMeasurements(){for(double[] bounds:new double[][]{{0,.001},{-13.25,0},{0,99.7},{-8,10},{0,0}}){double step=PopupHistory.tickStep(bounds[0],bounds[1]);assertTrue(step>=1);assertEquals(Math.rint(step),step,0);}assertEquals(1,PopupHistory.tickStep(0,.002),0);}
    @Test public void resolutionsRespectCatalogueAndUnloggedSources()throws Exception{MonitorData.Metric t=metric("t","temperature","","");assertFalse(PopupHistory.supports(t,"minute"));assertTrue(PopupHistory.supports(t,"hour"));assertFalse(PopupHistory.supports(null,"hour"));MonitorData.Metric m=metric("v","voltage","","");m.definition.put("resolutions",new JSONArray().put("day"));assertFalse(PopupHistory.supports(m,"minute"));assertTrue(PopupHistory.supports(m,"day"));}
    @Test public void picoVoltageOnlyBindsItsOwnRecordedSensor()throws Exception{List<MonitorData.Metric> metrics=MonitorData.catalogue(ContractTest.catalogue());Map<String,MonitorData.Datum> display=MonitorData.display(metrics,ContractTest.live(),0);MonitorData.Datum raw=display.get("battery:pico-voltage");assertNull(PopupHistory.binding(raw.id,raw,metrics));JSONObject definition=ContractTest.metric("raw-battery-voltage","pico","voltage","","",101);MonitorData.Metric same=new MonitorData.Metric(definition);metrics.add(same);assertSame(same,PopupHistory.binding(raw.id,raw,metrics));assertNull(PopupHistory.binding("battery:capacity.remaining",display.get("battery:capacity.remaining"),metrics));}
    @Test public void canonicalTitlesUseCorrectCellsAndSource()throws Exception{Map<String,MonitorData.Datum> display=MonitorData.display(MonitorData.catalogue(ContractTest.catalogue()),ContractTest.live(),0);assertEquals("Voltage Pico",PopupHistory.title("battery:pico-voltage",display.get("battery:pico-voltage"),"V[P]"));assertEquals("Remaining Battery Capacity",PopupHistory.title("battery:capacity.remaining",null,""));assertEquals("Time Remaining",PopupHistory.title("battery:capacity.timeRemaining",null,""));assertEquals("Cell [8]",PopupHistory.title("cell:7",null,"Cell 8"));assertEquals("SBMS0 Voltage",PopupHistory.title("x",ContractTest.find(display,"sbmsBattery","voltage"),""));}
    @Test public void malformedViewStateCannotImportCredentialsOrPresetState()throws Exception{PopupSelection original=selection(3,true);original.month="2025-09";original.power=original.bars=original.sum=true;PopupSelection restored=PopupSelection.parse(SavedJson.object(original.json().toString()));assertEquals(original.json().toString(),restored.json().toString());for(JSONObject bad:new JSONObject[]{original.json().put("token","private"),original.json().put("fixed","true"),original.json().put("period",4),original.json().put("period",1.5),original.json().put("month","2025-13"),original.json().put("month","1969-09")})try{PopupSelection.parse(bad);fail();}catch(Exception expected){}JSONObject entries=new JSONObject().put("a",original.json()).put("b",selection(0,false).json());JSONObject valid=new JSONObject().put("format",1).put("entries",entries);assertEquals(2,PopupSettingsStore.validate(valid).length());assertEquals(3,PopupSettingsStore.validate(valid).getJSONObject("a").getInt("period"));for(JSONObject bad:new JSONObject[]{new JSONObject(),valid.put("connection",new JSONObject()),new JSONObject().put("format",2).put("entries",entries),new JSONObject().put("format",1).put("entries",new JSONObject().put("a",1))})try{PopupSettingsStore.validate(bad);fail();}catch(Exception expected){} }
    @Test public void recordedMonthListUsesDailyRowsAndEarlierYearNames()throws Exception{MonitorData.Metric m=metric("t","temperature","","");JSONArray rows=new JSONArray();for(String start:new String[]{"2025-09-04T00:00:00Z","2026-09-05T00:00:00Z","2026-10-10T00:00:00Z"})rows.put(new JSONObject().put("start",start).put("end",Instant.parse(start).plusSeconds(86400).toString()).put("value",10));List<String> paths=new ArrayList<>();
        // Android JSONException is checked; build JSON outside the IOException-only connection factory.
        byte[] response=new JSONObject().put("apiVersion",1).put("schemaVersion",2).put("metric",m.definition).put("savedAt",now.toString()).put("rows",rows).toString().getBytes(StandardCharsets.UTF_8);
        ApiClient client=new ApiClient("https://history.example.invalid",String.join("",Collections.nCopies(64,"a")),url->{paths.add(url.getQuery());return new HttpURLConnection(url){public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public int getResponseCode(){return 200;}public InputStream getInputStream(){return new ByteArrayInputStream(response);}};});assertEquals(Arrays.asList(YearMonth.of(2026,10),YearMonth.of(2026,9),YearMonth.of(2025,9)),PopupHistory.months(client,m,now,utc));assertTrue(paths.get(0).contains("resolution=day"));assertEquals("September '25",PopupHistory.monthLabel(YearMonth.of(2025,9),now,utc));}
}
